const payload = $input.first().json;
const jobs = Array.isArray(payload.jobs) ? payload.jobs : [];

const skills = [
  ['n8n', 22],
  ['automation', 18],
  ['automations', 18],
  ['workflow', 12],
  ['artificial intelligence', 15],
  [' ai ', 12],
  ['llm', 16],
  ['agent', 10],
  ['api', 15],
  ['javascript', 16],
  ['typescript', 12],
  ['python', 16],
  ['web developer', 14],
  ['frontend', 12],
  ['backend', 12],
  ['full stack', 13],
  ['bot', 12],
  ['scraping', 16],
  ['integration', 15],
  ['unity', 18],
  ['roblox', 18],
  ['blender', 18],
  ['3d', 12],
  ['design', 9],
  ['ui/ux', 10],
  ['data', 7]
];

const valuableSignals = [
  'freelance', 'contract', 'contractor', 'part-time',
  'project', 'consultant', 'consulting', 'developer'
];

const badSignals = [
  'unpaid', 'volunteer', 'internship unpaid'
];

function cleanHtml(value = '') {
  return String(value)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

const results = [];

for (const job of jobs) {
  const description = cleanHtml(job.description || '');
  const text = `${job.title || ''} ${job.category || ''} ${job.job_type || ''} ${description}`.toLowerCase();

  let score = 0;
  const matches = [];

  for (const [term, points] of skills) {
    if (text.includes(term)) {
      score += points;
      matches.push(term.trim());
    }
  }

  for (const signal of valuableSignals) {
    if (text.includes(signal)) score += 4;
  }

  for (const signal of badSignals) {
    if (text.includes(signal)) score -= 40;
  }

  if (job.salary && String(job.salary).trim()) score += 12;
  if (job.candidate_required_location === 'Worldwide') score += 8;

  const published = job.publication_date ? new Date(job.publication_date) : null;
  if (published && !Number.isNaN(published.getTime())) {
    const ageHours = (Date.now() - published.getTime()) / 3600000;
    if (ageHours <= 24) score += 12;
    else if (ageHours <= 72) score += 8;
    else if (ageHours <= 168) score += 4;
  }

  if (matches.length === 0) continue;

  score = Math.max(0, Math.min(100, score));

  let decision = 'OBSERVAR';
  if (score >= 80) decision = 'PRIORIDAD';
  else if (score >= 60) decision = 'INVESTIGAR';
  else if (score < 35) decision = 'DESCARTAR';

  results.push({
    radar_score: score,
    decision,
    title: job.title || '',
    company: job.company_name || '',
    category: job.category || '',
    type: job.job_type || '',
    salary: job.salary || 'No publicado',
    location: job.candidate_required_location || '',
    published: job.publication_date || '',
    matches: [...new Set(matches)],
    url: job.url || '',
    source: 'Remotive',
    radar_note:
      score >= 80 ? 'Alta coincidencia. Revisar primero.' :
      score >= 60 ? 'Puede valer la pena. Investigar requisitos y pago.' :
      'Coincidencia parcial. No priorizar todavía.'
  });
}

results.sort((a, b) => b.radar_score - a.radar_score);

return results.slice(0, 30).map(result => ({ json: result }));
